/**
 * Where things sit in the scenes' app window (WIN_SIZE, 1440 x 900, default
 * 10px spacing), so a card can be framed with its edges only in the gaps:
 * between tile columns, between tile rows or terminal rows, or outside the
 * window. The numbers are the app's layout (src/grid/Canvas.tsx and its
 * stylesheet, components/home/app.css): the canvas under the 42px top bar has
 * SPACE of padding and SPACE between tiles; a tile's terminal starts under
 * its 37px header and stops above its 33px footer, in 15px rows.
 */
import { WIN_SIZE } from "../../home/Scenes";

/** The canvas's padding and the gap between tiles. */
export const SPACE = 10;
const TOP_BAR = 42;
const TILE_HEAD = 37;
const TILE_FOOT = 33;
const TERMINAL_ROW = 15;

/** One column's width in a `columns`-column grid. */
export const columnWidth = (columns: number, width = WIN_SIZE.width) => (width - SPACE * 2 - SPACE * (columns - 1)) / columns;

/** The middle of the gap after the first `n` columns of a `columns`-column grid. */
export const columnGap = (columns: number, n: number, width = WIN_SIZE.width) => SPACE + n * (columnWidth(columns, width) + SPACE) - SPACE / 2;

/** One tile row's height in a grid of `rows` rows sharing the canvas. */
const rowHeight = (rows: number, height: number) => (height - TOP_BAR - SPACE * 2 - SPACE * (rows - 1)) / rows;

/** The top of tile row `row` (from 0). */
export const rowTop = (rows: number, row: number, height = WIN_SIZE.height) => TOP_BAR + SPACE + row * (rowHeight(rows, height) + SPACE);

/** The window y between terminal rows `line` - 1 and `line` of the tiles in tile row `row`. */
export const betweenLines = (rows: number, row: number, line: number, height = WIN_SIZE.height) => rowTop(rows, row, height) + TILE_HEAD + line * TERMINAL_ROW;

/**
 * The first y at or below `y` where a horizontal card edge cuts nothing in a
 * grid of `rows` evenly shared rows: between two terminal rows, in the gap
 * between tile rows (or between the top bar and the tiles), or under the
 * tiles. Past the window it is `y` itself.
 */
export function cleanY(y: number, rows: number, height = WIN_SIZE.height): number {
  if (y <= 0 || y >= height) return y;
  for (let row = 0; row < rows; row += 1) {
    const top = rowTop(rows, row, height);
    // The canvas padding or row gap above this row.
    if (y <= top) return Math.max(y, top - SPACE);
    const lastLine = top + rowHeight(rows, height) - TILE_FOOT;
    for (let at = top + TILE_HEAD; at <= lastLine; at += TERMINAL_ROW) if (at >= y) return at;
  }
  // Under the last row: the canvas's bottom padding.
  const bottom = rowTop(rows, rows - 1, height) + rowHeight(rows, height);
  return Math.max(y, bottom + SPACE / 2);
}
